parameters.jsCode:
// Extract content dari OpenAI response
const content = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || '';

// Generate filename
const now = new Date();
const date = now.toISOString().split('T')[0];
const topic = $('Webhook').item.json.body.topic.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
const filename = `${date}-${topic}.php`;

// Prepare response
return {
  json: {
    success: true,
    filename: filename,
    content: content,
    topic: $('Webhook').item.json.body.topic,
    audience: $('Webhook').item.json.body.audience || 'millennial',
    slideCount: $('Webhook').item.json.body.slideCount || 7,
    generatedAt: now.toISOString(),
    downloadUrl: `https://your-domain.com/downloads/${filename}`
  }
};
